import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { storiesAPI } from '../services/api';
import { Bookmark, ExternalLink, User } from 'lucide-react';

interface Story {
  _id: string;
  title: string;
  url: string;
  points: number;
  author: string;
  postedAt: string;
  hackerNewsId: string;
  isBookmarked?: boolean;
}

const Bookmarks: React.FC = () => {
  const [bookmarks, setBookmarks] = useState<Story[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const { isAuthenticated } = useAuth();

  const fetchBookmarks = async () => {
    try {
      setLoading(true);
      const response = await storiesAPI.getBookmarks();
      setBookmarks(response.data.bookmarks);
    } catch (err: any) {
      setError('Failed to fetch bookmarks');
    } finally {
      setLoading(false);
    }
  };

  const handleBookmark = async (storyId: string) => {
    try {
      await storiesAPI.toggleBookmark(storyId);
      await fetchBookmarks();
    } catch (err: any) {
      setError('Failed to remove bookmark');
    }
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffInHours = Math.floor((now.getTime() - date.getTime()) / (1000 * 60 * 60));

    if (diffInHours < 1) {
      const diffInMinutes = Math.floor((now.getTime() - date.getTime()) / (1000 * 60));
      return `${diffInMinutes} minute${diffInMinutes !== 1 ? 's' : ''} ago`;
    } else if (diffInHours < 24) {
      return `${diffInHours} hour${diffInHours !== 1 ? 's' : ''} ago`;
    } else {
      const diffInDays = Math.floor(diffInHours / 24);
      return `${diffInDays} day${diffInDays !== 1 ? 's' : ''} ago`;
    }
  };

  useEffect(() => {
    if (isAuthenticated) {
      fetchBookmarks();
    }
  }, [isAuthenticated]);

  if (!isAuthenticated) {
    return (
      <div className="text-center py-12">
        <h2 className="text-2xl font-bold text-gray-900 mb-4">Authentication Required</h2>
        <p className="text-gray-600 mb-6">
          Please <Link to="/login" className="text-orange-600 hover:text-orange-700 font-medium">sign in</Link> to view your bookmarks.
        </p>
      </div>
    );
  }

  return (
    <div>
      <div className="flex items-center space-x-2 mb-8">
        <Bookmark className="text-orange-600" size={24} />
        <h1 className="text-3xl font-bold text-gray-900">My Bookmarks</h1>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-md mb-6">
          {error}
        </div>
      )}

      {loading ? (
        <div className="flex justify-center items-center h-64">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-orange-600"></div>
        </div>
      ) : bookmarks.length === 0 ? (
        <div className="text-center py-12">
          <Bookmark size={48} className="text-gray-300 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-gray-900 mb-2">No bookmarks yet</h3>
          <p className="text-gray-600 mb-6">
            Start bookmarking your favorite stories from the <Link to="/" className="text-orange-600 hover:text-orange-700 font-medium">home page</Link>.
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          {bookmarks.map((story, index) => (
            <div key={story._id} className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 hover:shadow-md transition-shadow">
              <div className="flex items-start space-x-3">
                <span className="text-gray-500 font-medium text-sm w-6">{index + 1}.</span>

                <div className="flex-1">
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <h3 className="text-lg font-medium text-gray-900 mb-1">
                        <a
                          href={story.url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="hn-link hover:text-orange-600 flex items-center space-x-1"
                        >
                          <span>{story.title}</span>
                          <ExternalLink size={14} className="text-gray-400" />
                        </a>
                      </h3>

                      <div className="hn-meta flex items-center space-x-4 text-sm">
                        <span className="flex items-center space-x-1">
                          <span className="font-medium">{story.points}</span>
                          <span>points</span>
                        </span>

                        <span className="flex items-center space-x-1">
                          <User size={14} />
                          <span>{story.author}</span>
                        </span>

                        <span>{formatDate(story.postedAt)}</span>
                      </div>
                    </div>

                    <button
                      onClick={() => handleBookmark(story._id)}
                      className="bookmark-btn ml-4 p-2 rounded-full hover:bg-gray-100"
                      title="Remove bookmark"
                    >
                      <Bookmark 
                        size={18} 
                        className="bookmarked fill-current text-orange-600"
                      />
                    </button>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Bookmarks;
